const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- complex helpers (hoisted) for the Descartes circle theorem ----
function cadd(a,b){return [a[0]+b[0],a[1]+b[1]];}
function csub(a,b){return [a[0]-b[0],a[1]-b[1]];}
function cmul(a,b){return [a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0]];}
function cscl(a,s){return [a[0]*s,a[1]*s];}
function csqrt(a){const m=Math.hypot(a[0],a[1]); const re=Math.sqrt((m+a[0])/2); let im=Math.sqrt(Math.max(0,(m-a[0])/2)); if(a[1]<0)im=-im; return [re,im];}
function tang(A,B,tol){const d=Math.hypot(A.z[0]-B.z[0],A.z[1]-B.z[1]); const ra=1/Math.abs(A.b), rb=1/Math.abs(B.b); return Math.abs(d-(ra+rb))<tol || Math.abs(d-Math.abs(ra-rb))<tol;}
function buildGasket(cx,cy,R,rMin,Nmax,frn,depth){
  const f = 0.5 + (frn(1)-0.5)*0.26;
  const r1=R*f, r2=R*(1-f), tol=R*0.02;
  const c0={b:-1/R, z:[cx,cy], gen:0};
  const c1={b: 1/r1, z:[cx-(R-r1),cy], gen:1};
  const c2={b: 1/r2, z:[cx+(R-r2),cy], gen:1};
  const all=[c0,c1,c2], q=[[c0,c1,c2]], seen=new Set();
  const kOf=c=>Math.round(c.z[0])+'_'+Math.round(c.z[1])+'_'+Math.round(1/Math.abs(c.b));
  let guard=0;
  while(q.length && all.length<Nmax && guard++<Nmax*6){
    const [a,b,c]=q.shift();
    const s=a.b+b.b+c.b, rt=2*Math.sqrt(Math.abs(a.b*b.b+b.b*c.b+c.b*a.b));
    const wa=cscl(a.z,a.b), wb=cscl(b.z,b.b), wc=cscl(c.z,c.b);
    const wsum=cadd(cadd(wa,wb),wc);
    const wrt=cscl(csqrt(cadd(cadd(cmul(wa,wb),cmul(wb,wc)),cmul(wc,wa))),2);
    const gg=Math.max(a.gen,b.gen,c.gen)+1;
    for(const cand of [[s+rt,cadd(wsum,wrt)],[s-rt,csub(wsum,wrt)]]){
      const b4=cand[0], w4=cand[1];
      if(!isFinite(b4)||b4===0) continue;
      const r=1/Math.abs(b4); if(r<rMin||r>R) continue;
      const nc={b:b4, z:cscl(w4,1/b4), gen:gg};
      const dd=Math.hypot(nc.z[0]-cx,nc.z[1]-cy); if(dd+r>R+tol) continue;
      if(!(tang(nc,a,tol)&&tang(nc,b,tol)&&tang(nc,c,tol))) continue;
      const k=kOf(nc); if(seen.has(k)) continue; seen.add(k);
      all.push(nc); q.push([a,b,nc]); q.push([a,c,nc]); q.push([b,c,nc]);
      if(all.length>=Nmax) break;
    }
  }
  return all;
}

const W=width,H=height,u=Math.min(W,H);
const style=P.style, hue=md(P.hue,360), en=clp(P.energy,0,1)*(.5+.7*K.intensity);
const dens=clp(P.density,0,1), ga=clp(P.alpha,0,100)/100;
const sec=Math.floor(md(K.section,8));

// ---- cached gasket: rebuild ONLY on size / seed / density / scale / anchor buckets ----
const depth=Math.round(3+dens*4);
const Nmax=Math.round(80+dens*320);
const rMin=u*(0.016-dens*0.0125);              // density thins the pixel floor => far more small circles at max
const scl=clp(P.scale,0.6,1.5);
const cx0=clp(P.x,.15,.85)*W, cy0=clp(P.y,.15,.85)*H, R=u*0.52*scl;
const key=W+'x'+H+'|'+P.seed+'|'+Math.round(dens*8)+'|'+Math.round(scl*10)+'|'+Math.round(P.x*16)+'|'+Math.round(P.y*16);
if(S.key!==key){
  S.key=key;
  const raw=buildGasket(cx0, cy0, R, rMin, Nmax, fr, depth);
  const ang=fr(9)*TAU, ca=Math.cos(ang), sa=Math.sin(ang);   // seed rotation => visibly different layouts
  for(const c of raw){ const dx=c.z[0]-cx0, dy=c.z[1]-cy0; c.z=[cx0+dx*ca-dy*sa, cy0+dx*sa+dy*ca]; }
  let lo=1e9,hi=-1e9; for(const c of raw){const L=Math.log(Math.abs(c.b)); if(L<lo)lo=L; if(L>hi)hi=L;}
  for(const c of raw){ c.tp=(Math.log(Math.abs(c.b))-lo)/(hi-lo+1e-6); c.ph=fr(c.z[0]*0.7+c.z[1]*1.31+3); }
  raw.sort((p,q)=>p.tp-q.tp);
  S.g=raw;
}
const G=S.g;
const lx=P.x*W, ly=P.y*H;
const expo=0.72+en*0.5;

// ---- per-style background (genart owns bg; never near-black at default) ----
noStroke();
let bgH,bgS,bgB;
if(style==='gold-leaf'){ bgH=28; bgS=48; bgB=13; }
else if(style==='neon-outline'){ bgH=md(hue+205,360); bgS=55; bgB=9; }
else if(style==='blueprint'){ bgH=210; bgS=62; bgB=15; }
else if(style==='riso-duotone'){ bgH=42; bgS=10; bgB=93; }
else { bgH=md(hue,360); bgS=30; bgB=6; } // chiaroscuro
if(ga>=0.999) background(bgH,bgS,bgB);

// gold-leaf: warm radial hearth behind the disk so corners aren't dead-black
if(style==='gold-leaf' && ga>=0.999){
  push(); blendMode(ADD); noStroke();
  fill(36,70,60,9); circle(lx,ly,R*2.7);
  fill(45,55,80,7); circle(lx,ly,R*1.7);
  blendMode(BLEND); pop();
}

// ---- reveal scalar: drifts on K.t so deeper gens fade IN/OUT (never re-phases, never strobes) ----
const rev = (P.act==='pulse') ? 1
          : (P.act==='drift') ? clp(0.55+0.45*Math.sin(K.t*0.04*P.speed),0,1)
          : clp((0.42+0.5*(0.5+0.5*Math.sin(K.t*0.05*P.speed)))*(0.62+0.55*K.intensity),0,1);

// misregistration / ink blend setup
if(style==='riso-duotone') blendMode(MULTIPLY);

for(let i=0;i<G.length;i++){
  const c=G[i], x=c.z[0], y=c.z[1], tp=c.tp;
  const vis=clp((rev-tp)*6,0,1); if(vis<=0.02) continue;
  const breathe = 1 + 0.07*Math.sin(K.t*0.6*P.speed + c.ph*TAU) + (K.pulse*0.11 + A.bass*0.16)*en*(tp<0.42?1:0.3);
  const r=(1/Math.abs(c.b))*breathe; if(r<u*0.004) continue;
  // HSB cosine ramp across depth (iq idea, HSB-native) + slow K.t + section drift
  const drift = K.t*1.4 + sec*7;
  const hh=md(hue + 66*Math.cos(TAU*tp*0.6) + drift, 360);
  const ss=clp(50+38*Math.cos(TAU*(tp*0.6+0.15)),0,100);
  const bb=clp((58+34*Math.cos(TAU*(tp*0.6+0.30)))*expo,0,100);

  if(style==='gold-leaf'){
    // nested gold coins: warm hue band, brighter as they shrink; metallic sheen offset by light dir
    const gh=md(hue - 8 + 26*Math.cos(TAU*tp*0.7) + K.t*0.7, 360);
    const gsat=clp(88-30*tp - 10*Math.cos(TAU*tp),35,96);
    const gbr=clp((34+52*(1-tp)+8*Math.sin(K.t*0.5+c.ph*TAU))*expo,22,96);
    noStroke(); fill(gh,gsat,gbr,100*vis*ga); circle(x,y,r*2);
    if(r>u*0.028){
      const dx=(lx-x), dy=(ly-y), dl=Math.hypot(dx,dy)+1;
      noStroke(); fill(md(gh+6,360),clp(gsat-28,0,100),clp(gbr+18,0,100),70*vis*ga);
      circle(x+dx/dl*r*0.34, y+dy/dl*r*0.34, r*0.82);
      fill(48,18,100,55*vis*ga); circle(x+dx/dl*r*0.5, y+dy/dl*r*0.5, r*0.24);
    }
  } else if(style==='riso-duotone'){
    // two spot inks, misregistered; overprint darkens on MULTIPLY -> print duotone
    const mo=r*0.11*(1+0.45*Math.sin(K.t*0.5+c.ph*TAU));
    noStroke();
    fill(md(hue+298,360),58,94,90*vis*ga); circle(x-mo,y+mo*0.5,r*2);
    fill(md(hue+168,360),62,86,84*vis*ga); circle(x+mo,y-mo*0.4,r*2);
  } else if(style==='chiaroscuro'){
