    const dx=(lx-x), dy=(ly-y), dl=Math.hypot(dx,dy)+1, ox=dx/dl, oy=dy/dl;
    noStroke();
    fill(md(hue+tp*40,360),clp(38+tp*20,0,100),clp(9+6*(1-tp),0,100),100*vis*ga); circle(x,y,r*2);
    fill(hh,clp(ss-10,0,100),clp(bb*0.7,0,100),92*vis*ga); circle(x+ox*r*0.34,y+oy*r*0.34,r*1.42);
