    noFill(); stroke(196,70,88,clp(58+en*30,0,100)*vis); strokeWeight(clp(r*0.035,0.5,1.7));
    circle(x,y,r*2);
    if(r>u*0.05){ stroke(196,45,70,40*vis); strokeWeight(0.7); circle(x,y,r*1.3); circle(x,y,r*0.5);
      stroke(196,60,95,55*vis); strokeWeight(0.8); line(x-r*0.14,y,x+r*0.14,y); line(x,y-r*0.14,x,y+r*0.14); }
    noStroke();
  } else {
    // neon-outline base: faint filled disk; the ADD glow pass below lights the rings
    const nh=md(200 + tp*168 + K.t*1.4, 360);
    noStroke(); fill(nh,72,clp(bb*0.34,0,100),46*vis*ga); circle(x,y,r*2);
  }
}
if(style==='riso-duotone') blendMode(BLEND);

// ---- neon glow pass: only the largest few rings, shadowBlur capped <=24 (PROBE <=~30) ----
if(style==='neon-outline'){
