  drawingContext.shadowBlur=0; blendMode(BLEND); pop();
}

// ---- audio sparkle on treble: partial ADD wash on the anchor, never full-frame (won't strobe) ----
if(en>0.02 && (A.treble>0.02 || A.rms>0.02) && ga>=0.999){
